egend -->\n    <g transform=\"translate(28, 590)\">\n      <text font-size=\"12\" fill=\"#7fa6c9\">Harbors: \u2693 3:1 Any (4) \u2022 \ud83e\udeb5 Wood 2:1 \u2022 \ud83e\uddf1 Brick 2:1 \u2022 \ud83d\udc11 Sheep 2:1 \u2022 \ud83c\udf3e Wheat 2:1 \u2022 \u26f0 Ore 2:1</text>\n    </g>\n  </g>\n\n  <!-- BOTTOM FULL-WIDTH PRIMARY ACTION BAR -->\n  <g id=\"Bottom-Primary-Action-Bar\" transform=\"translate(60, 755)\">\n    <!-- Ready / Start Banner -->\n    <rect width=\"1320\" height=\"95\" rx=\"14\" fill=\"#08233d\" stroke=\"#1e5285\" stroke-width=\"1.5\" filter=\"url(#shadow-lg)\"/>\n    \n    <g transform=\"translate(32, 28)\">\n      <text font-family=\"'Bricolage Grotesque', sans-serif\" font-size=\"20\" font-weight=\"bold\" fill=\"#ffffff\">All 4 players are ready with selected colors!</text>\n      <text y=\"22\" font-size=\"13\" fill=\"#86efac\">The match is primed to start. Alice (Host) holds the launch trigger.</text>\n    </g>\n\n    <!-- START MATCH BIG GLOWING BUTTON -->\n    <g transform=\"translate(1020, 20)\" filter=\"url(#glow-gold)\">\n      <rect width=\"265\" height=\"55\" rx=\"12\" fill=\"#f06800\" stroke=\"#ffaa44\" stroke-width=\"2.5\"/>\n      <text x=\"132\" y=\"34\" font-family=\"'Bricolage Grotesque', sans-serif\" font-size=\"20\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">START GAME \u279c</text>\n    </g>\n  </g>\n</svg>"
